        g.ell(cx, 54, 5, 5, BR.d); g.ell(cx, 54, 3.4, 3.4, BR.h); g.ell(cx, 54, 1.6, 1.6, '#3a8a4a');
        g.r(56, 64, 24, 4, BR.d); g.r(56, 64, 24, 1, BR.h);
