        g.poly([[cx, 64], [cx + 20, 64], [cx + 32, 108], [cx + 24, 102], [cx + 18, 112], [cx + 10, 104], [cx + 2, 114], [cx, 80]], AR.d);
        g.line(cx - 18, 68, cx - 28, 104, 1, AR.h); g.r(cx - 2, 64, 4, 46, G); g.r(cx - 2, 64, 1, 46, GH);
        // breastplate
