      g.poly([a,[mid[0]-dy/n*w,mid[1]+dx/n*w],b,[mid[0]+dy/n*w,mid[1]-dx/n*w]],i%2?F.m:F2.m);g.line(b[0]-(b[0]-a[0])*.16,b[1]-(b[1]-a[1])*.16,b[0],b[1],1.4,color.tip);
